INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106001, 1, 7, "2030/12/17 14:59:59", 0, 0, -363, 7001, 1, "キャル", "2015/12/17 15:00:00", 1, 0, "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105901, 1, 7, "2030/12/17 14:59:59", 0, 0, -363, 7002, 1, "コッコロ", "2015/12/17 15:00:00", 1, 0, "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105801, 1, 7, "2030/12/17 14:59:59", 0, 0, -363, 7003, 1, "ペコリーヌ", "2015/12/17 15:00:00", 1, 0, "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105801, 1, 10, "2030/12/17 14:59:59", 0, 0, -363, 10001, 1, "ペコリーヌ", "2015/12/17 15:00:00", 1, 0, "ジュエルを食べ物…\nいえ、貴重品と交換できます！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106001, 1, 10, "2030/12/17 14:59:59", 0, 0, -363, 10002, 1, "キャル", "2015/12/17 15:00:00", 1, 0, "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105901, 1, 10, "2030/12/17 14:59:59", 0, 0, -363, 10003, 1, "コッコロ", "2015/12/17 15:00:00", 1, 0, "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106401, 2, 10, "2030/12/17 14:59:59", 2104010, 0, -363, 10004, 1, "シェフィ", "2015/12/17 15:00:00", 1, 0, "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105801, 1, 12, "2030/12/17 14:59:59", 0, 0, -416.5, 12001, 1, "ペコリーヌ", "2015/12/17 15:00:00", 1, 0, "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106001, 1, 13, "2030/12/17 14:59:59", 0, 0, -363, 13001, 1, "キャル", "2015/12/17 15:00:00", 1, 0, "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105901, 1, 13, "2030/12/17 14:59:59", 0, 0, -363, 13002, 1, "コッコロ", "2015/12/17 15:00:00", 1, 0, "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106401, 2, 13, "2030/12/17 14:59:59", 2104010, 0, -363, 13003, 1, "シェフィ", "2015/12/17 15:00:00", 1, 0, "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105801, 1, 13, "2030/12/17 14:59:59", 0, 0, -363, 13004, 1, "ペコリーヌ", "2015/12/17 15:00:00", 1, 0, "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105901, 1, 14, "2030/12/17 14:59:59", 0, 0, -363, 14001, 1, "コッコロ", "2015/12/17 15:00:00", 1, 0, "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106401, 2, 14, "2030/12/17 14:59:59", 2104010, 0, -363, 14002, 1, "シェフィ", "2015/12/17 15:00:00", 1, 0, "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105801, 1, 14, "2030/12/17 14:59:59", 0, 0, -363, 14003, 1, "ペコリーヌ", "2015/12/17 15:00:00", 1, 0, "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106001, 1, 14, "2030/12/17 14:59:59", 0, 0, -363, 14004, 1, "キャル", "2015/12/17 15:00:00", 1, 0, "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105901, 1, 15, "2030/12/17 14:59:59", 0, 0, -470, 15001, 1, "コッコロ", "2015/12/17 15:00:00", 1, 0, "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106401, 2, 16, "2030/12/17 14:59:59", 2104010, 0, -363, 16001, 1, "シェフィ", "2015/12/17 15:00:00", 1, 0, "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105801, 1, 16, "2030/12/17 14:59:59", 0, 0, -363, 16002, 1, "ペコリーヌ", "2015/12/17 15:00:00", 1, 0, "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106001, 1, 16, "2030/12/17 14:59:59", 0, 0, -363, 16003, 1, "キャル", "2015/12/17 15:00:00", 1, 0, "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105901, 1, 16, "2030/12/17 14:59:59", 0, 0, -363, 16004, 1, "コッコロ", "2015/12/17 15:00:00", 1, 0, "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105901, 1, 17, "2030/12/17 14:59:59", 0, 0, -363, 17002, 1, "コッコロ", "2015/12/17 15:00:00", 1, 0, " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106001, 1, 25, "2030/12/17 14:59:59", 0, 0, -363, 17004, 1, "キャル", "2015/12/17 15:00:00", 1, 0, "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105901, 1, 25, "2030/12/17 14:59:59", 0, 0, -363, 17005, 1, "コッコロ", "2015/12/17 15:00:00", 1, 0, "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106401, 2, 25, "2030/12/17 14:59:59", 2104010, 0, -363, 17006, 1, "シェフィ", "2015/12/17 15:00:00", 1, 0, "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105801, 1, 25, "2030/12/17 14:59:59", 0, 0, -363, 17007, 1, "ペコリーヌ", "2015/12/17 15:00:00", 1, 0, "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 18, "2030/12/17 14:59:59", 0, 0, -363, 18001, 1, "カリン", "2015/12/17 15:00:00", 1, 0, "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 18, "2030/12/17 14:59:59", 0, 0, -363, 18002, 2, "カリン", "2015/12/17 15:00:00", 1, 0, "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 19, "2030/12/17 14:59:59", 0, 0, -470, 19001, 3, "カリン", "2015/12/17 15:00:00", 1, 0, "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 19, "2030/12/17 14:59:59", 0, 0, -470, 19002, 4, "カリン", "2015/12/17 15:00:00", 1, 0, "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 20, "2030/12/17 14:59:59", 0, 0, -470, 20001, 5, "カリン", "2015/12/17 15:00:00", 1, 0, "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 20, "2030/12/17 14:59:59", 0, 0, -470, 20002, 6, "カリン", "2015/12/17 15:00:00", 1, 0, "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106001, 1, 21, "2030/12/17 14:59:59", 0, 0, -363, 21001, 1, "キャル", "2015/12/17 15:00:00", 1, 0, "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105901, 1, 21, "2030/12/17 14:59:59", 0, 0, -363, 21002, 1, "コッコロ", "2015/12/17 15:00:00", 1, 0, "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106401, 2, 21, "2030/12/17 14:59:59", 2104010, 0, -363, 21003, 1, "シェフィ", "2015/12/17 15:00:00", 1, 0, "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105801, 1, 21, "2030/12/17 14:59:59", 0, 0, -363, 21004, 1, "ペコリーヌ", "2015/12/17 15:00:00", 1, 0, "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 22, "2030/12/17 14:59:59", 0, 0, -430, 22001, 1, "カリン", "2015/12/17 15:00:00", 1, 0, "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 22, "2030/12/17 14:59:59", 0, 0, -430, 22002, 2, "カリン", "2015/12/17 15:00:00", 1, 0, "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 23, "2030/12/17 14:59:59", 0, 0, -430, 23001, 3, "カリン", "2015/12/17 15:00:00", 1, 0, "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 23, "2030/12/17 14:59:59", 0, 0, -430, 23002, 4, "カリン", "2015/12/17 15:00:00", 1, 0, "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (4.08, 109001, 1, 24, "2030/12/17 14:59:59", 0, 8, -385, 24001, 1, "エリコ（バレンタイン）", "2019/01/31 12:00:00", 2, 10011, "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (5, 109001, 1, 24, "2030/12/17 14:59:59", 0, 8, -385, 24002, 2, "エリコ（バレンタイン）", "2019/01/31 12:00:00", 2, 10011, "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (10.11, 109001, 1, 24, "2030/12/17 14:59:59", 0, 8, -385, 24003, 3, "エリコ（バレンタイン）", "2019/01/31 12:00:00", 2, 10011, "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (4, 109001, 1, 24, "2030/12/17 14:59:59", 0, 8, -385, 24004, 4, "エリコ（バレンタイン）", "2019/01/31 12:00:00", 2, 10011, "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (6, 109001, 1, 24, "2030/12/17 14:59:59", 0, 8, -385, 24005, 5, "エリコ（バレンタイン）", "2019/01/31 12:00:00", 2, 10011, "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 109002, 1, 24, "2030/12/17 14:59:59", 0, 0, 0, 24006, 6, "エリコ（バレンタイン）", "2019/01/31 12:00:00", 1, 10011, "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 109002, 1, 24, "2030/12/17 14:59:59", 0, 0, 0, 24007, 7, "エリコ（バレンタイン）", "2019/01/31 12:00:00", 1, 10011, "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 109002, 1, 24, "2030/12/17 14:59:59", 0, 0, 0, 24008, 8, "エリコ（バレンタイン）", "2019/01/31 12:00:00", 1, 10011, "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 109002, 1, 24, "2030/12/17 14:59:59", 0, 0, 0, 24009, 9, "エリコ（バレンタイン）", "2019/01/31 12:00:00", 1, 10011, "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 109002, 1, 24, "2030/12/17 14:59:59", 0, 0, 0, 24010, 10, "エリコ（バレンタイン）", "2019/01/31 12:00:00", 1, 10011, "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (2.12, 109101, 1, 24, "2030/12/17 14:59:59", 0, 8, -385, 24011, 1, "シズル（バレンタイン）", "2019/01/31 12:00:00", 2, 10011, "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (4.19, 109101, 5, 24, "2030/12/17 14:59:59", 0, 8, -385, 24012, 2, "シズル（バレンタイン）", "2019/01/31 12:00:00", 2, 10011, "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (2.3, 109101, 2, 24, "2030/12/17 14:59:59", 0, 8, -385, 24013, 3, "シズル（バレンタイン）", "2019/01/31 12:00:00", 4, 10011, "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 109102, 1, 24, "2030/12/17 14:59:59", 0, 0, 0, 24014, 4, "シズル（バレンタイン）", "2019/01/31 12:00:00", 1, 10011, "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (5.23, 109101, 5, 24, "2030/12/17 14:59:59", 0, 8, -385, 24015, 5, "シズル（バレンタイン）", "2019/01/31 12:00:00", 2, 10011, "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 109102, 1, 24, "2030/12/17 14:59:59", 0, 0, 0, 24016, 6, "シズル（バレンタイン）", "2019/01/31 12:00:00", 1, 10011, "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (5.01, 109101, 1, 24, "2030/12/17 14:59:59", 0, 8, -385, 24017, 7, "シズル（バレンタイン）", "2019/01/31 12:00:00", 2, 10011, "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 109102, 1, 24, "2030/12/17 14:59:59", 0, 0, 0, 24018, 8, "シズル（バレンタイン）", "2019/01/31 12:00:00", 1, 10011, "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 109102, 1, 24, "2030/12/17 14:59:59", 0, 0, 0, 24019, 9, "シズル（バレンタイン）", "2019/01/31 12:00:00", 1, 10011, "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 109102, 1, 24, "2030/12/17 14:59:59", 0, 0, 0, 24020, 10, "シズル（バレンタイン）", "2019/01/31 12:00:00", 1, 10011, "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106401, 2, 26, "2030/12/17 14:59:59", 2104010, 0, -363, 26001, 1, "シェフィ", "2015/12/17 15:00:00", 1, 0, "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105801, 1, 26, "2030/12/17 14:59:59", 0, 0, -363, 26002, 1, "ペコリーヌ", "2015/12/17 15:00:00", 1, 0, "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106001, 1, 26, "2030/12/17 14:59:59", 0, 0, -363, 26003, 1, "キャル", "2015/12/17 15:00:00", 1, 0, "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105901, 1, 26, "2030/12/17 14:59:59", 0, 0, -363, 26004, 1, "コッコロ", "2015/12/17 15:00:00", 1, 0, "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106401, 2, 27, "2030/12/17 14:59:59", 2104010, 0, -363, 27001, 1, "シェフィ", "2015/12/17 15:00:00", 1, 0, "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105801, 1, 27, "2030/12/17 14:59:59", 0, 0, -363, 27002, 1, "ペコリーヌ", "2015/12/17 15:00:00", 1, 0, "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106001, 1, 27, "2030/12/17 14:59:59", 0, 0, -363, 27003, 1, "キャル", "2015/12/17 15:00:00", 1, 0, "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105901, 1, 27, "2030/12/17 14:59:59", 0, 0, -363, 27004, 1, "コッコロ", "2015/12/17 15:00:00", 1, 0, "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 28, "2030/12/17 14:59:59", 0, 0, -363, 28001, 1, "カリン", "2019/09/24 15:00:00", 1, 0, "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 28, "2030/12/17 14:59:59", 0, 0, -363, 28002, 2, "カリン", "2019/09/24 15:00:00", 1, 0, "ギルド管理協会です\nフレンドに関しては\nこちらでご確認ください");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 29, "2030/12/17 14:59:59", 0, 0, -409, 29001, 3, "カリン", "2019/09/24 15:00:00", 1, 0, "こちらがフレンドの\n皆さんです\n素敵な関係を\n築いてくださいね！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 29, "2030/12/17 14:59:59", 0, 0, -409, 29002, 4, "カリン", "2019/09/24 15:00:00", 1, 0, "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 30, "2030/12/17 14:59:59", 0, 0, -409, 30001, 5, "カリン", "2019/09/24 15:00:00", 1, 0, "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 30, "2030/12/17 14:59:59", 0, 0, -409, 30002, 6, "カリン", "2019/09/24 15:00:00", 1, 0, "フレンドの申請や\n承認ができますよ\nどうぞ、良き交流を！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 31, "2030/12/17 14:59:59", 0, 0, -409, 31001, 7, "カリン", "2019/10/31 12:00:00", 1, 0, "バトルをして力比べを\nしてみましょう！\n実力が試されますね、\n頑張ってください！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 31, "2030/12/17 14:59:59", 0, 0, -409, 31002, 8, "カリン", "2019/10/31 12:00:00", 1, 0, "気になるパーティと\nバトルをしてみましょう！\nどちらが勝利するのか、\n私も楽しみにしていますね");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 32, "2020/01/04 4:59:59", 0, 0, -409, 32001, 1, "カリン", "2019/12/20 5:00:00", 1, 0, "ルーキーの皆さんのために\n特別なミッションを\nご用意いたしました！\nぜひ、挑戦してください！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 32, "2020/01/04 4:59:59", 0, 0, -409, 32002, 2, "カリン", "2019/12/20 5:00:00", 1, 0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 33, "2020/01/04 4:59:59", 0, 0, -409, 33001, 3, "カリン", "2019/12/20 5:00:00", 1, 0, "フレンドになって\n初心者の方を応援しましょう！\n素敵な報酬が待っていますよ！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 33, "2020/01/04 4:59:59", 0, 0, -409, 33002, 4, "カリン", "2019/12/20 5:00:00", 1, 0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 34, "2020/01/10 11:59:59", 0, 0, -409, 34001, 5, "カリン", "2020/01/04 5:00:00", 1, 0, "お疲れ様でした！\nミッションの報酬の受け取りは\nこちらからできますよ！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 34, "2020/01/10 11:59:59", 0, 0, -409, 34002, 6, "カリン", "2020/01/04 5:00:00", 1, 0, "ミッション報酬の受け取りは\nこちら！\n受け取り漏れの無いように\n気を付けてくださいね！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (5.3, 105801, 1, 38, "2030/12/17 14:59:59", 0, 0, -458, 38001, 1, "ペコリーヌ", "2015/12/17 15:00:00", 2, 0, "過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (6.5, 105801, 1, 38, "2030/12/17 14:59:59", 0, 0, -458, 38002, 2, "ペコリーヌ", "2015/12/17 15:00:00", 2, 0, "これまでのイベントで登場した\n限定キャラを仲間にできたり\nメモリーピースが手に入る\nみたいですよ。やばいですね☆");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105801, 3, 39, "2020/04/08 23:59:59", 0, 9999, 9999, 39005, 0, "ペコリーヌ", "2020/04/01", 3, 0, "");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 190801, 1, 40, "2030/12/17 14:59:59", 0, 0, -430, 40001, 2, "カリン", "2015/12/17 15:00:00", 1, 0, "これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106401, 1, 41, "2030/12/17 14:59:59", 2104010, 0, -363, 41001, 1, "シェフィ", "2015/12/17 15:00:00", 1, 0, "ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105801, 1, 41, "2030/12/17 14:59:59", 0, 0, -363, 41002, 1, "ペコリーヌ", "2015/12/17 15:00:00", 1, 0, "ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106001, 1, 41, "2030/12/17 14:59:59", 0, 0, -363, 41003, 1, "キャル", "2015/12/17 15:00:00", 1, 0, "ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105901, 1, 41, "2030/12/17 14:59:59", 0, 0, -363, 41004, 1, "コッコロ", "2015/12/17 15:00:00", 1, 0, "腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105901, 1, 42, "2030/12/17 14:59:59", 0, 0, -416.5, 42001, 1, "コッコロ", "2015/12/17 15:00:00", 1, 0, "訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106401, 1, 42, "2030/12/17 14:59:59", 2104010, 0, -416.5, 42002, 1, "シェフィ", "2015/12/17 15:00:00", 1, 0, "目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105801, 1, 42, "2030/12/17 14:59:59", 0, 0, -416.5, 42003, 1, "ペコリーヌ", "2015/12/17 15:00:00", 1, 0, "腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106001, 1, 42, "2030/12/17 14:59:59", 0, 0, -416.5, 42004, 1, "キャル", "2015/12/17 15:00:00", 1, 0, "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105801, 1, 43, "2030/12/17 14:59:59", 0, 0, -363, 43001, 1, "ペコリーヌ", "2015/12/17 15:00:00", 1, 0, "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 105901, 1, 43, "2030/12/17 14:59:59", 0, 0, -363, 43002, 1, "コッコロ", "2015/12/17 15:00:00", 1, 0, "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 106001, 1, 43, "2030/12/17 14:59:59", 0, 0, -363, 43003, 1, "キャル", "2015/12/17 15:00:00", 1, 0, "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 123001, 1, 44, "2030/12/17 14:59:59", 0, 0, -416.5, 43004, 1, "アメス", "2015/12/17 15:00:00", 1, 0, "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 123001, 1, 44, "2030/12/17 14:59:59", 0, 0, -416.5, 43005, 2, "アメス", "2015/12/17 15:00:00", 1, 0, "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (5.79, 123001, 1, 45, "2030/12/17 14:59:59", 0, 0, -416.5, 43006, 3, "アメス", "2015/12/17 15:00:00", 2, 0, "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 123001, 1, 46, "2030/12/17 14:59:59", 0, 0, -371.5, 46001, 1, "アメス", "2015/12/17 15:00:00", 1, 0, "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 104901, 2, 47, "2030/12/17 14:59:59", 0, 0, -416.5, 47001, 1, "シズル", "2015/12/17 15:00:00", 2, 0, "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (9.32, 101101, 1, 47, "2030/12/17 14:59:59", 0, 0, -416.5, 47002, 1, "リノ", "2015/12/17 15:00:00", 2, 0, "ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES (0, 104901, 2, 48, "2030/12/17 14:59:59", 0, 0, -470, 48001, 0, "シズル", "2015/12/17 15:00:00", 2, 0, "");
